from research import *
import re, ast
P = ROOT / 'sources'
REV = '5c4886908584029761b579af026dcfb627c84070'

def cite(path, needle):
    lines = (P / path).read_text(encoding='utf-8').splitlines()
    line = next((i for i, s in enumerate(lines, 1) if needle in s))
    return f'https://github.com/pytorch/pytorch/blob/{REV}/{path}#L{line}'

def doc(symbol):
    f = 'torch/_tensor_docs.py' if symbol.startswith('torch.Tensor.new_') else 'torch/_torch_docs.py'
    name = symbol.split('.')[-1]
    module = ast.parse((P / f).read_text(encoding='utf-8'))
    for expr in module.body:
        if not isinstance(expr, ast.Expr) or not isinstance(expr.value, ast.Call):
            continue
        call = expr.value
        if not call.args:
            continue
        a = call.args[0]
        matches = isinstance(a, ast.Constant) and a.value == name if f.endswith('_tensor_docs.py') else ast.unparse(a) == symbol
        if matches:
            text = '\n'.join((x.value for x in ast.walk(call.args[1]) if isinstance(x, ast.Constant) and isinstance(x.value, str)))
            parts = [x.strip() for x in text.splitlines() if x.strip()]
            sig = parts[0]
            if sig.endswith('\\'):
                sig = sig[:-1] + parts[1]
            return {'source': f'https://github.com/pytorch/pytorch/blob/{REV}/{f}#L{call.lineno}', 'signature': sig}
    raise ValueError(symbol)
